export enum SampleType {
  URINE = 'Urine (ECBU)',
  BLOOD = 'Blood Culture',
  PUS = 'Pus/Wound',
  CSF = 'CSF',
  STOOL = 'Stool',
  RESPIRATORY = 'Respiratory',
  OTHER = 'Other'
}

export enum GramStatus {
  UNKNOWN = 'Unknown',
  GPC = 'Gram Positive Cocci',
  GNB = 'Gram Negative Bacilli',
  GPB = 'Gram Positive Bacilli',
  GNC = 'Gram Negative Cocci',
  YEAST = 'Yeast'
}

export enum TestType {
  CATALASE = 'Catalase',
  COAGULASE = 'Coagulase',
  OXIDASE = 'Oxidase',
  KLIGLER = 'Kligler (Glu/Lac/Gas/H2S)',
  MANNITOL = 'Mannitol Motility',
  UREA_INDOLE = 'Urea-Indole',
  CITRATE = 'Citrate (Simmons)'
}

export enum TestResultValue {
  PENDING = 'Pending',
  POSITIVE = 'Positive (+)',
  NEGATIVE = 'Negative (-)',
  INDETERMINATE = 'Indeterminate',
  // Specific for Kligler
  ALK_ACID = 'K/A (Red/Yellow)',
  ACID_ACID = 'A/A (Yellow/Yellow)',
  ALK_ALK = 'K/K (Red/Red)',
}

export interface TestEntry {
  id: string;
  type: TestType;
  result: TestResultValue;
  notes?: string;
  timestamp: number;
}

export interface PlateObservation {
  id: string;
  media: string; // e.g. "Blood Agar", "MacConkey"
  morphology: string; // e.g. "S-type, creamy, beta-hemolysis"
  growth: 'No Growth' | 'Scanty' | 'Moderate' | 'Heavy';
  imageUrl?: string;
}

export interface Sample {
  id: string;
  patientId: string;
  type: SampleType;
  collectionDate: string;
  gramStatus: GramStatus;
  plates: PlateObservation[];
  tests: TestEntry[];
  aiAnalysis?: string;
  status: 'Processing' | 'Ready for ID' | 'Completed';
}

import { SampleType, GramStatus, TestType, TestResultValue } from './types';

export const MEDIA_TYPES = [
  'Blood Agar',
  'Chocolate Agar',
  'MacConkey Agar',
  'CLED Agar',
  'Mannitol Salt Agar',
  'Sabouraud Dextrose Agar',
  'Hektoen Enteric Agar',
  'Mueller-Hinton'
];

export const INITIAL_TESTS_GNB = [
  TestType.OXIDASE
];

export const INITIAL_TESTS_GPC = [
  TestType.CATALASE
];

export const MINI_GALLERIE = [
  TestType.KLIGLER,
  TestType.CITRATE,
  TestType.MANNITOL,
  TestType.UREA_INDOLE
];

export const TEST_OPTIONS = {
  [TestType.OXIDASE]: [TestResultValue.POSITIVE, TestResultValue.NEGATIVE],
  [TestType.CATALASE]: [TestResultValue.POSITIVE, TestResultValue.NEGATIVE],
  [TestType.COAGULASE]: [TestResultValue.POSITIVE, TestResultValue.NEGATIVE],
  [TestType.UREA_INDOLE]: [TestResultValue.POSITIVE, TestResultValue.NEGATIVE],
  [TestType.CITRATE]: [TestResultValue.POSITIVE, TestResultValue.NEGATIVE],
  [TestType.MANNITOL]: [TestResultValue.POSITIVE, TestResultValue.NEGATIVE],
  [TestType.KLIGLER]: [TestResultValue.ALK_ACID, TestResultValue.ACID_ACID, TestResultValue.ALK_ALK],
};

