import { GoogleGenAI } from "@google/genai";
import { Sample, GramStatus, TestEntry } from "../types";

// Initialize Gemini Client
// IMPORTANT: process.env.API_KEY must be set in the environment
const apiKey = process.env.API_KEY || ''; 
// We will handle the missing key case gracefully in the UI, but here we instantiate if present.
// If the key is empty, the calls will fail, and we catch that.

const getAiClient = () => {
    if (!apiKey) {
        throw new Error("API Key missing");
    }
    return new GoogleGenAI({ apiKey });
};

export const analyzeBacteriologyCase = async (sample: Sample, query?: string): Promise<string> => {
  try {
    const ai = getAiClient();

    // Construct a context-rich prompt
    const plateText = sample.plates.map(p => `- On ${p.media}: ${p.growth} growth. ${p.morphology}`).join('\n');
    const testText = sample.tests.length > 0 
      ? sample.tests.map(t => `- ${t.type}: ${t.result}`).join('\n')
      : 'No biochemical tests performed yet.';

    const systemInstruction = `
      You are an expert Clinical Microbiologist assisting a lab technician.
      Your goal is to guide the "Exploitation of Plate Reading" workflow.

      Based on the provided Gram stain, plate morphology, and any preliminary spot tests (Oxidase/Catalase),
      suggest the next logical steps.

      Rules:
      1. If Gram Negative Bacilli (GNB):
         - Check Oxidase.
         - If Oxidase Negative -> Suggest Enterobacteriaceae workup (Mini Gallerie: Kligler, Urea-Indole, Mannitol, Citrate).
         - If Oxidase Positive -> Suggest Pseudomonas/Non-fermenters workup.
      2. If Gram Positive Cocci (GPC):
         - Check Catalase.
         - If Catalase Positive -> Suggest Coagulase (Staph).
         - If Catalase Negative -> Suggest Strep grouping/Hemolysis check.
      3. Be concise. Provide a brief rationale for the suspected germ list.
      4. Suggest if the user is ready for Vitek/API 20 identification.
    `;

    const userPrompt = `
      Sample Type: ${sample.type}
      Gram Status: ${sample.gramStatus}

      Plate Observations:
      ${plateText}

      Current Test Results:
      ${testText}

      User Query: ${query || "What are the recommended follow-up tests and likely identification?"}
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: userPrompt,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.4, // Keep it fairly deterministic and professional
      }
    });

    return response.text || "No analysis generated.";
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return "Unable to contact AI Advisor. Please check your network or API Key configuration.";
  }
};

import React from 'react';
import { Sample, GramStatus } from '../types';
import { FlaskConical, Droplet, Activity, Bug } from 'lucide-react';

interface SampleCardProps {
  sample: Sample;
  onClick: (sample: Sample) => void;
  isActive: boolean;
}

const SampleCard: React.FC<SampleCardProps> = ({ sample, onClick, isActive }) => {
  const getIcon = () => {
    switch (sample.type) {
      case 'Urine (ECBU)': return <FlaskConical className="w-5 h-5 text-yellow-500" />;
      case 'Blood Culture': return <Droplet className="w-5 h-5 text-red-500" />;
      default: return <Activity className="w-5 h-5 text-teal-500" />;
    }
  };

  return (
    <div 
      onClick={() => onClick(sample)}
      className={`p-4 rounded-xl cursor-pointer transition-all duration-200 border ${
        isActive 
          ? 'bg-teal-50 border-teal-500 shadow-md' 
          : 'bg-white border-slate-200 hover:border-teal-300 hover:shadow-sm'
      }`}
    >
      <div className="flex justify-between items-start mb-2">
        <div className="flex items-center space-x-2">
          <div className={`p-2 rounded-lg ${isActive ? 'bg-white' : 'bg-slate-100'}`}>
            {getIcon()}
          </div>
          <div>
            <h3 className="font-semibold text-slate-800 text-sm">{sample.id}</h3>
            <p className="text-xs text-slate-500">{sample.patientId}</p>
          </div>
        </div>
        <span className={`text-xs px-2 py-1 rounded-full font-medium ${
          sample.status === 'Ready for ID' ? 'bg-green-100 text-green-700' : 'bg-blue-50 text-blue-600'
        }`}>
          {sample.status}
        </span>
      </div>

      <div className="flex items-center space-x-2 mt-3 text-xs text-slate-600 bg-slate-50 p-2 rounded">
        <Bug className="w-3 h-3" />
        <span className="truncate">
          {sample.gramStatus === GramStatus.UNKNOWN ? 'Gram: Pending' : sample.gramStatus}
        </span>
      </div>
    </div>
  );
};

export default SampleCard;

import React from 'react';
import { TestType, TestResultValue } from '../types';

interface TestTubeProps {
  type: TestType;
  result: TestResultValue;
  onClick: () => void;
}

const TestTube: React.FC<TestTubeProps> = ({ type, result, onClick }) => {

  const getColors = () => {
    if (result === TestResultValue.PENDING) return 'bg-gray-200 border-gray-300 text-gray-400';

    // Kligler Logic
    if (type === TestType.KLIGLER) {
      if (result === TestResultValue.ACID_ACID) return 'bg-yellow-400 border-yellow-500 text-yellow-900'; // A/A
      if (result === TestResultValue.ALK_ACID) return 'bg-gradient-to-b from-red-500 to-yellow-400 border-red-600 text-white'; // K/A
      if (result === TestResultValue.ALK_ALK) return 'bg-red-500 border-red-600 text-white'; // K/K
    }

    // Urea Indole
    if (type === TestType.UREA_INDOLE) {
      if (result === TestResultValue.POSITIVE) return 'bg-pink-500 border-pink-600 text-white'; // Urease +
      if (result === TestResultValue.NEGATIVE) return 'bg-yellow-100 border-yellow-300 text-yellow-800'; // Urease -
    }

    // Citrate
    if (type === TestType.CITRATE) {
      if (result === TestResultValue.POSITIVE) return 'bg-blue-600 border-blue-700 text-white'; // Citrate + (Blue)
      if (result === TestResultValue.NEGATIVE) return 'bg-green-500 border-green-600 text-white'; // Citrate - (Green)
    }

    // Standard Positive/Negative for others
    if (result === TestResultValue.POSITIVE) return 'bg-teal-500 border-teal-600 text-white';
    if (result === TestResultValue.NEGATIVE) return 'bg-rose-100 border-rose-300 text-rose-800';

    return 'bg-slate-100 border-slate-300 text-slate-600';
  };

  return (
    <div 
      onClick={onClick}
      className={`relative h-24 w-16 rounded-b-2xl rounded-t-md border-2 flex flex-col items-center justify-end p-2 cursor-pointer transition-transform hover:scale-105 shadow-sm ${getColors()}`}
    >
      <div className="absolute top-[-10px] w-full text-center">
         <span className="text-[10px] uppercase font-bold tracking-tighter text-slate-500 bg-white/80 px-1 rounded shadow-sm border border-slate-200">
          {type.split(' ')[0]}
         </span>
      </div>
      <span className="text-xs font-bold text-center leading-tight">
        {result === TestResultValue.PENDING ? '?' : result.replace(/\(.\)/, '')}
      </span>
    </div>
  );
};

export default TestTube;

import React, { useState, useEffect } from 'react';
import { Sample, GramStatus, TestType, TestResultValue, PlateObservation, TestEntry } from '../types';
import { MEDIA_TYPES, TEST_OPTIONS, MINI_GALLERIE } from '../constants';
import { analyzeBacteriologyCase } from '../services/geminiService';
import TestTube from './TestTube';
import { Plus, Trash2, Microscope, Wand2, FlaskConical, ArrowRight, Loader2, Save } from 'lucide-react';

interface WorkBenchProps {
  sample: Sample;
  onUpdateSample: (updated: Sample) => void;
}

const WorkBench: React.FC<WorkBenchProps> = ({ sample, onUpdateSample }) => {
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [activeTab, setActiveTab] = useState<'plates' | 'biochem' | 'id'>('plates');

  // Local state for forms
  const [newPlateMedia, setNewPlateMedia] = useState(MEDIA_TYPES[0]);
  const [newPlateMorph, setNewPlateMorph] = useState('');
  const [newPlateGrowth, setNewPlateGrowth] = useState<PlateObservation['growth']>('Moderate');

  const updateGram = (status: GramStatus) => {
    onUpdateSample({ ...sample, gramStatus: status });
  };

  const addPlateObservation = () => {
    if (!newPlateMorph) return;
    const newPlate: PlateObservation = {
      id: Date.now().toString(),
      media: newPlateMedia,
      morphology: newPlateMorph,
      growth: newPlateGrowth
    };
    onUpdateSample({ ...sample, plates: [...sample.plates, newPlate] });
    setNewPlateMorph('');
  };

  const removePlate = (id: string) => {
    onUpdateSample({ ...sample, plates: sample.plates.filter(p => p.id !== id) });
  };

  const setTestResult = (type: TestType, result: TestResultValue) => {
    const existing = sample.tests.find(t => t.type === type);
    let newTests = [...sample.tests];

    if (existing) {
      newTests = newTests.map(t => t.type === type ? { ...t, result } : t);
    } else {
      newTests.push({
        id: Date.now().toString(),
        type,
        result,
        timestamp: Date.now()
      });
    }
    onUpdateSample({ ...sample, tests: newTests });
  };

  const handleAIAnalysis = async () => {
    setIsAnalyzing(true);
    const advice = await analyzeBacteriologyCase(sample);
    onUpdateSample({ ...sample, aiAnalysis: advice });
    setIsAnalyzing(false);
    setActiveTab('id'); // Switch to results tab
  };

  // Logic for suggesting tests
  const getSuggestedTests = () => {
    const suggestions: TestType[] = [];
    const hasTest = (t: TestType) => sample.tests.some(test => test.type === t);

    if (sample.gramStatus === GramStatus.GNB) {
      if (!hasTest(TestType.OXIDASE)) suggestions.push(TestType.OXIDASE);
      else {
        const ox = sample.tests.find(t => t.type === TestType.OXIDASE);
        if (ox?.result === TestResultValue.NEGATIVE) {
          // If Oxidase -, suggest Mini Gallerie
          MINI_GALLERIE.forEach(t => {
            if (!hasTest(t)) suggestions.push(t);
          });
        }
      }
    } else if (sample.gramStatus === GramStatus.GPC) {
      if (!hasTest(TestType.CATALASE)) suggestions.push(TestType.CATALASE);
      else {
        const cat = sample.tests.find(t => t.type === TestType.CATALASE);
        if (cat?.result === TestResultValue.POSITIVE && !hasTest(TestType.COAGULASE)) {
          suggestions.push(TestType.COAGULASE);
        }
      }
    }
    return suggestions;
  };

  const suggestedTests = getSuggestedTests();

  return (
    <div className="flex flex-col h-full bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">

      {/* Header */}
      <div className="bg-slate-50 border-b border-slate-200 p-4 flex justify-between items-center">
        <div>
          <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
            <Microscope className="text-teal-600" />
            Workspace: <span className="font-mono text-teal-700">{sample.id}</span>
          </h2>
          <p className="text-sm text-slate-500">{sample.type} | {sample.collectionDate.split('T')[0]}</p>
        </div>
        <div className="flex space-x-2">
           <button 
             onClick={handleAIAnalysis}
             className="flex items-center gap-2 bg-gradient-to-r from-violet-600 to-indigo-600 text-white px-4 py-2 rounded-lg hover:shadow-lg hover:scale-105 transition-all text-sm font-medium disabled:opacity-70"
             disabled={isAnalyzing}
           >
             {isAnalyzing ? <Loader2 className="animate-spin w-4 h-4"/> : <Wand2 className="w-4 h-4" />}
             AI Analysis
           </button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-slate-200 bg-white sticky top-0 z-10">
        <button 
          onClick={() => setActiveTab('plates')}
          className={`px-6 py-3 text-sm font-medium border-b-2 transition-colors ${activeTab === 'plates' ? 'border-teal-500 text-teal-700' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
        >
          1. Plate Reading & Gram
        </button>
        <button 
          onClick={() => setActiveTab('biochem')}
          className={`px-6 py-3 text-sm font-medium border-b-2 transition-colors ${activeTab === 'biochem' ? 'border-teal-500 text-teal-700' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
        >
          2. Biochemical Tests
        </button>
        <button 
          onClick={() => setActiveTab('id')}
          className={`px-6 py-3 text-sm font-medium border-b-2 transition-colors ${activeTab === 'id' ? 'border-teal-500 text-teal-700' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
        >
          3. Identification & Summary
        </button>
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-y-auto p-6 bg-slate-50/50">

        {/* TAB 1: PLATES */}
        {activeTab === 'plates' && (
          <div className="space-y-6 max-w-4xl mx-auto">

            {/* Gram Stain Section */}
            <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
              <h3 className="font-semibold text-slate-800 mb-3 flex items-center gap-2">
                <div className="w-6 h-6 rounded bg-purple-100 text-purple-600 flex items-center justify-center font-bold text-xs">G</div>
                Gram Stain Status
              </h3>
              <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                {Object.values(GramStatus).map((status) => (
                  <button
                    key={status}
                    onClick={() => updateGram(status as GramStatus)}
                    className={`px-3 py-2 text-sm rounded-lg border transition-all text-left ${
                      sample.gramStatus === status 
                        ? 'bg-purple-50 border-purple-500 text-purple-700 ring-1 ring-purple-500' 
                        : 'bg-white border-slate-200 text-slate-600 hover:border-purple-300'
                    }`}
                  >
                    {status}
                  </button>
                ))}
              </div>
            </div>

            {/* Plate List */}
            <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
              <h3 className="font-semibold text-slate-800 mb-4 flex items-center gap-2">
                 <div className="w-6 h-6 rounded bg-teal-100 text-teal-600 flex items-center justify-center font-bold text-xs">P</div>
                 Observed Plates
              </h3>

              <div className="space-y-3 mb-6">
                {sample.plates.map(plate => (
                  <div key={plate.id} className="flex items-start justify-between p-3 bg-slate-50 rounded-lg border border-slate-100">
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-semibold text-slate-700">{plate.media}</span>
                        <span className={`text-xs px-2 py-0.5 rounded-full ${
                          plate.growth === 'Heavy' ? 'bg-red-100 text-red-700' : 'bg-green-100 text-green-700'
                        }`}>{plate.growth}</span>
                      </div>
                      <p className="text-sm text-slate-600 mt-1">{plate.morphology}</p>
                    </div>
                    <button onClick={() => removePlate(plate.id)} className="text-slate-400 hover:text-red-500">
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                ))}
                {sample.plates.length === 0 && <p className="text-sm text-slate-400 italic">No plates recorded yet.</p>}
              </div>

              {/* Add New Plate Form */}
              <div className="bg-teal-50/50 p-4 rounded-lg border border-teal-100">
                <h4 className="text-sm font-semibold text-teal-800 mb-3">Add Observation</h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3 mb-3">
                  <select 
                    value={newPlateMedia}
                    onChange={(e) => setNewPlateMedia(e.target.value)}
                    className="p-2 rounded border border-slate-300 text-sm focus:ring-2 focus:ring-teal-500 outline-none"
                  >
                    {MEDIA_TYPES.map(m => <option key={m} value={m}>{m}</option>)}
                  </select>
                  <select
                    value={newPlateGrowth}
                    onChange={(e) => setNewPlateGrowth(e.target.value as any)}
                    className="p-2 rounded border border-slate-300 text-sm focus:ring-2 focus:ring-teal-500 outline-none"
                  >
                    {['No Growth', 'Scanty', 'Moderate', 'Heavy'].map(g => <option key={g} value={g}>{g}</option>)}
                  </select>
                </div>
                <textarea
                  placeholder="Describe colony morphology (size, color, hemolysis, smell, lactose ferm...)"
                  value={newPlateMorph}
                  onChange={(e) => setNewPlateMorph(e.target.value)}
                  className="w-full p-2 rounded border border-slate-300 text-sm mb-3 focus:ring-2 focus:ring-teal-500 outline-none h-20 resize-none"
                />
                <button 
                  onClick={addPlateObservation}
                  className="w-full bg-teal-600 text-white py-2 rounded-lg hover:bg-teal-700 transition-colors flex items-center justify-center gap-2 text-sm font-medium"
                >
                  <Plus className="w-4 h-4" /> Add Plate Reading
                </button>
              </div>
            </div>

            <div className="flex justify-end">
              <button 
                onClick={() => setActiveTab('biochem')}
                className="flex items-center gap-2 bg-slate-800 text-white px-6 py-2 rounded-lg hover:bg-slate-700"
              >
                Proceed to Tests <ArrowRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        )}

        {/* TAB 2: BIOCHEM */}
        {activeTab === 'biochem' && (
          <div className="space-y-8 max-w-5xl mx-auto">

            {/* Suggested Workflow */}
            <div className="bg-blue-50 p-4 rounded-xl border border-blue-100">
              <h3 className="font-semibold text-blue-800 mb-2 flex items-center gap-2">
                <Activity className="w-5 h-5" /> Recommended Follow-up
              </h3>
              <p className="text-sm text-blue-700 mb-3">
                Based on <strong>{sample.gramStatus}</strong>, performing the following tests is recommended:
              </p>
              <div className="flex flex-wrap gap-2">
                {suggestedTests.length > 0 ? suggestedTests.map(t => (
                  <span key={t} className="px-3 py-1 bg-white text-blue-600 text-xs font-bold border border-blue-200 rounded-full shadow-sm animate-pulse">
                    {t}
                  </span>
                )) : <span className="text-sm italic text-blue-500">Please complete Gram stain first or check logic.</span>}
              </div>
            </div>

            {/* Test Bench Visualization */}
            <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
              <h3 className="font-semibold text-slate-800 mb-6 border-b pb-2">Bench Tests (Click to Toggle Result)</h3>

              {/* Flex container for tubes */}
              <div className="flex flex-wrap gap-8 justify-center items-end min-h-[140px]">
                {/* Always show relevant tests or already added tests */}
                {Array.from(new Set([...suggestedTests, ...sample.tests.map(t => t.type)])).map(testType => {
                  const existingTest = sample.tests.find(t => t.type === testType);
                  const currentResult = existingTest ? existingTest.result : TestResultValue.PENDING;

                  return (
                    <div key={testType} className="flex flex-col items-center gap-2">
                       <TestTube 
                          type={testType} 
                          result={currentResult}
                          onClick={() => {
                            // Cycle through options
                            const options = TEST_OPTIONS[testType] || [];
                            const currIdx = options.indexOf(currentResult);
                            const nextResult = currIdx === -1 ? options[0] : options[(currIdx + 1) % options.length];
                            setTestResult(testType, nextResult);
                          }} 
                       />

                       {/* Dropdown fallback/override */}
                       <select 
                        className="text-[10px] w-24 p-1 border rounded bg-slate-50"
                        value={currentResult}
                        onChange={(e) => setTestResult(testType, e.target.value as TestResultValue)}
                       >
                         <option value={TestResultValue.PENDING}>Pending</option>
                         {TEST_OPTIONS[testType]?.map(opt => (
                           <option key={opt} value={opt}>{opt}</option>
                         ))}
                       </select>
                    </div>
                  );
                })}

                {/* Button to manually add other tests if logic misses them */}
